import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"63、【既济】 离下坎上","description":"横渠易说 - 63、【既济】 离下坎上","frontmatter":{"title":"63、【既济】 离下坎上","description":"横渠易说 - 63、【既济】 离下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/065.md","filePath":"zh/classics/hengqu/065.md"}'),l={name:"zh/classics/hengqu/065.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_63、【既济】-离下坎上" tabindex="-1">63、【既济】 离下坎上 <a class="header-anchor" href="#_63、【既济】-离下坎上" aria-label="Permalink to “63、【既济】 离下坎上”">​</a></h1><h3 id="彖曰-既济亨-小者亨也-利贞-刚柔正而位当也。-初吉-柔得中也-终止则乱-其道穷也。" tabindex="-1">彖曰：“既济亨”，小者亨也，“利贞”，刚柔正而位当也。“初吉”，柔得中也；终止则乱，其道穷也。 <a class="header-anchor" href="#彖曰-既济亨-小者亨也-利贞-刚柔正而位当也。-初吉-柔得中也-终止则乱-其道穷也。" aria-label="Permalink to “彖曰：“既济亨”，小者亨也，“利贞”，刚柔正而位当也。“初吉”，柔得中也；终止则乱，其道穷也。”">​</a></h3><h3 id="象曰-水在火上-既济-君子以思患而豫防之。" tabindex="-1">象曰：水在火上，既济，君子以思患而豫防之。 <a class="header-anchor" href="#象曰-水在火上-既济-君子以思患而豫防之。" aria-label="Permalink to “象曰：水在火上，既济，君子以思患而豫防之。”">​</a></h3><p>通其变然后可久，故止则乱也。</p><h3 id="初九-曳其轮-濡其尾-无咎。-象曰-曳其轮-义无咎也。" tabindex="-1">初九，曳其轮，濡其尾，无咎。 象曰：“曳其轮”，义无咎也。 <a class="header-anchor" href="#初九-曳其轮-濡其尾-无咎。-象曰-曳其轮-义无咎也。" aria-label="Permalink to “初九，曳其轮，濡其尾，无咎。 象曰：“曳其轮”，义无咎也。”">​</a></h3><h3 id="六二-妇丧其茀勿逐-七日得。-象曰-七日得-以中道也。" tabindex="-1">六二，妇丧其茀勿逐，七日得。 象曰：“七日得”，以中道也。 <a class="header-anchor" href="#六二-妇丧其茀勿逐-七日得。-象曰-七日得-以中道也。" aria-label="Permalink to “六二，妇丧其茀勿逐，七日得。 象曰：“七日得”，以中道也。”">​</a></h3><h3 id="九三-高宗伐鬼方-三年克之-小人勿用。-象曰-三年克之-惫也。" tabindex="-1">九三，高宗伐鬼方，三年克之，小人勿用。 象曰：“三年克之”，惫也。 <a class="header-anchor" href="#九三-高宗伐鬼方-三年克之-小人勿用。-象曰-三年克之-惫也。" aria-label="Permalink to “九三，高宗伐鬼方，三年克之，小人勿用。 象曰：“三年克之”，惫也。”">​</a></h3><p>上六险而应，此处卦之未济以终乱者也，故以比鬼方。九三以阳居阳，文明而正，故用师虽久，困而必克，小人用之，取亡之道也。</p><h3 id="六四-繻有衣袽-终日戒。-象曰-终日戒-有所疑也。" tabindex="-1">六四，繻有衣袽，终日戒。 象曰：“终日戒”，有所疑也。 <a class="header-anchor" href="#六四-繻有衣袽-终日戒。-象曰-终日戒-有所疑也。" aria-label="Permalink to “六四，繻有衣袽，终日戒。 象曰：“终日戒”，有所疑也。”">​</a></h3><h3 id="九五-东邻杀牛-不如西邻之禴祭实受其福。-象曰-东邻杀牛-不如西邻之时也。-实受其福-吉大来也。" tabindex="-1">九五，东邻杀牛，不如西邻之禴祭实受其福。 象曰：“东邻杀牛”，不如西邻之时也。“实受其福”，吉大来也。 <a class="header-anchor" href="#九五-东邻杀牛-不如西邻之禴祭实受其福。-象曰-东邻杀牛-不如西邻之时也。-实受其福-吉大来也。" aria-label="Permalink to “九五，东邻杀牛，不如西邻之禴祭实受其福。 象曰：“东邻杀牛”，不如西邻之时也。“实受其福”，吉大来也。”">​</a></h3><p>东邻，上六也；西邻，六四也。过于济，厚也；几于中，时也。济而合礼，虽薄受福。九五既济之主，举上与下，其义之得不言而着也。</p><h3 id="上六-濡其首-厉。-象曰-濡其首-厉-何可久也" tabindex="-1">上六，濡其首，厉。 象曰：“濡其首，厉”，何可久也! <a class="header-anchor" href="#上六-濡其首-厉。-象曰-濡其首-厉-何可久也" aria-label="Permalink to “上六，濡其首，厉。 象曰：“濡其首，厉”，何可久也!”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
